// --- Required n8n Variables check ---
const requiredVars = ['HOME_COORDS', 'HOME_RADIUS_METERS', 'DRESS_REMINDER_INTERVALS', 'TRACKING_INTERVAL_TIERS'];
const missingVars = requiredVars.filter(k => !$vars[k]);
if (missingVars.length) {
  throw new Error(`Missing n8n Variables: ${missingVars.join(', ')}. Set them in Settings → Variables before activating workflows.`);
}

// WF4 State Machine — processes location updates and transitions event states
const body = $('Location Update').item.json.body;
const userLat = parseFloat(body.lat);
const userLng = parseFloat(body.lng);
const accuracy = parseFloat(body.accuracy) || 50;
const userId = body.user_id;
const now = new Date();

// Read all daily_plan rows
const allRows = $input.all().map(i => i.json);
const today = DateTime.now().setZone('Europe/Bucharest').toISODate(); // timezone-aware

// Filter to this user's active events today
const terminalStates = ['arrived', 'cancelled', 'skipped', 'expired'];
const trackableEvents = allRows.filter(row =>
  row.user_id === userId
  && row.plan_date === today
  && !terminalStates.includes(row.current_state)
  && (row.is_online !== 'TRUE' && row.is_online !== true)
  && row.location_coords
);

if (trackableEvents.length === 0) {
  return { json: { action: 'none', reason: 'no trackable events', recommended_interval: 15, user_is_at_home: false, at_home_source: 'unknown', at_home_updates: null } };
}

// Pick the event with the nearest departure_time
trackableEvents.sort((a, b) => new Date(a.departure_time) - new Date(b.departure_time));
const event = trackableEvents[0];

// --- Consent-safety gate ---
if (event.cancel_requested_at) {
  const cancelTime = new Date(event.cancel_requested_at);
  const sixtyMinAgo = new Date(now.getTime() - 60 * 60 * 1000);
  if (cancelTime > sixtyMinAgo) {
    return { json: {
      action: 'force_cancel',
      event_id: event.event_id,
      current_state: 'cancelled',
      state_version: (parseInt(event.state_version) || 0) + 1,
      stop_tracking: true
    }};
  }
}

// --- Haversine distance helper ---
function haversine(lat1, lng1, lat2, lng2) {
  const R = 6371000; // meters
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLng = (lng2 - lng1) * Math.PI / 180;
  const a = Math.sin(dLat/2)**2 +
    Math.cos(lat1*Math.PI/180) * Math.cos(lat2*Math.PI/180) * Math.sin(dLng/2)**2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
}

// Parse coordinates
const [originLat, originLng] = (event.origin_coords || '').split(',').map(Number);
const [destLat, destLng] = (event.location_coords || '').split(',').map(Number);
const depTime = new Date(event.departure_time);
const currentState = event.current_state;
const stateVersion = parseInt(event.state_version) || 0;

let newState = currentState;
let shouldUpdate = false;

// --- State transitions ---
if (currentState === 'planned' && now >= new Date(depTime.getTime() - 20 * 60 * 1000)) {
  newState = 'should_leave';
  shouldUpdate = true;
}

// Departure detection: user is >500m from origin AND within 30 min of departure
const distFromOrigin = haversine(userLat, userLng, originLat, originLng);
const departureThreshold = Math.max(500, accuracy * 2);
if ((currentState === 'planned' || currentState === 'should_leave')
    && distFromOrigin > departureThreshold
    && now >= new Date(depTime.getTime() - 30 * 60 * 1000)) {
  newState = 'departed';
  shouldUpdate = true;
}

// Arrival detection: user is within max(200m, accuracy*2) of event location
// Single check is sufficient — the dynamic radius (max(200m, accuracy*2)) already
// absorbs GPS jitter by expanding the threshold when accuracy is poor
const distFromDest = haversine(userLat, userLng, destLat, destLng);
const arrivalRadius = Math.max(200, accuracy * 2);
if (currentState === 'departed' && distFromDest <= arrivalRadius) {
  newState = 'arrived';
  shouldUpdate = true;
}

// Should-leave alert: still home past departure time
let sendUrgentAlert = false;
if (currentState === 'should_leave' && distFromOrigin < 200 && now > depTime) {
  sendUrgentAlert = true;
}

// Check if this is the last trackable event
const remainingAfterThis = trackableEvents.filter(e => e.event_id !== event.event_id);
const stopTracking = newState === 'arrived' && remainingAfterThis.length === 0;

// Multi-event origin recalculation (on arrival)
// When arriving at event A, update the origin for ALL remaining events (B, C, D, ...)
// This handles chains like Home → A → B → C: arriving at A updates B and C's origin to A's location.
// ALL remaining events get updated (not just those with origin_type !== 'event') because
// the most recent arrival is always the correct origin — e.g., arriving at B should update
// C's origin to B's location even though A already set it to A's location.
let eventsToUpdate = [];
if (newState === 'arrived' && remainingAfterThis.length > 0) {
  for (const remainingEvent of remainingAfterThis) {
    eventsToUpdate.push({
      event_id: remainingEvent.event_id,
      new_origin_coords: event.location_coords,
      new_origin_type: 'event'
    });
  }
}

// --- At-home detection (runs on every location update) ---
// WiFi-first: if Tasker reports WiFi connection to home SSID, trust it over GPS.
// WiFi is cheaper, faster, and works indoors where GPS is unreliable.
const HOME_COORDS = $vars.HOME_COORDS;                    // e.g. "44.4268,26.1025"
const HOME_RADIUS_METERS = parseInt($vars.HOME_RADIUS_METERS); // e.g. "200" → 200
const WIFI_FRESHNESS_MS = 20 * 60 * 1000; // 20 minutes — WiFi signal considered stale after this
const [homeLat, homeLng] = HOME_COORDS.split(',').map(Number);

const wifiAtHome = body.wifi_at_home;
const wifiAtHomeAt = body.wifi_at_home_at ? parseInt(body.wifi_at_home_at) * 1000 : null; // Tasker sends epoch seconds
const wifiIsFresh = wifiAtHomeAt && (now.getTime() - wifiAtHomeAt) < WIFI_FRESHNESS_MS;

let userIsAtHome;
let atHomeSource;
if (wifiIsFresh && (wifiAtHome === '1' || wifiAtHome === 1 || wifiAtHome === true || wifiAtHome === 'true')) {
  userIsAtHome = true;
  atHomeSource = 'wifi';
} else if (wifiIsFresh && (wifiAtHome === '0' || wifiAtHome === 0 || wifiAtHome === false || wifiAtHome === 'false')) {
  // WiFi explicitly says not at home — still fall through to GPS as a safety check.
  // User might be in the yard (no WiFi but within 200m). GPS decides.
  const distFromHome = haversine(userLat, userLng, homeLat, homeLng);
  userIsAtHome = distFromHome <= HOME_RADIUS_METERS;
  atHomeSource = 'gps_after_wifi_disconnect';
} else {
  // No WiFi data or stale — pure GPS fallback
  const distFromHome = haversine(userLat, userLng, homeLat, homeLng);
  userIsAtHome = distFromHome <= HOME_RADIUS_METERS;
  atHomeSource = 'gps';
}

// Find all non-terminal physical events for this user today whose at_home differs
const eventsNeedingAtHomeUpdate = allRows.filter(row =>
  row.user_id === userId
  && row.plan_date === today
  && !terminalStates.includes(row.current_state)
  && (row.is_online !== 'TRUE' && row.is_online !== true)
  && ((row.at_home === 'TRUE' || row.at_home === true) !== userIsAtHome)
);

// --- Dynamic polling interval calculation ---
// Uses TRACKING_INTERVAL_TIERS from $vars (format: "60:20,30:10,15:5,5:3")
// Each tier is "minutes_until_departure:interval_minutes", sorted descending by threshold.
// Falls back to sensible defaults if parsing fails.
const tierStr = $vars.TRACKING_INTERVAL_TIERS; // e.g. "60:20,30:10,15:5,5:3"
let intervalTiers = [
  { withinMin: 60, interval: 20 },
  { withinMin: 30, interval: 10 },
  { withinMin: 15, interval: 5 },
  { withinMin: 5, interval: 3 }
];
if (tierStr) {
  intervalTiers = tierStr.split(',').map(pair => {
    const [withinMin, interval] = pair.split(':').map(Number);
    return { withinMin, interval };
  }).filter(t => !isNaN(t.withinMin) && !isNaN(t.interval))
    .sort((a, b) => b.withinMin - a.withinMin); // descending
}

const minsToDeparture = (depTime.getTime() - now.getTime()) / 60000;
let recommendedInterval;
if (newState === 'departed') {
  // Commuting — use the tightest tier (smallest interval) for arrival detection
  recommendedInterval = intervalTiers[intervalTiers.length - 1]?.interval || 5;
} else if (remainingAfterThis.length === 0 && newState === 'arrived') {
  recommendedInterval = 15;  // last event done — tracking will stop soon
} else {
  // Find matching tier: first tier whose threshold is >= minsToDeparture
  recommendedInterval = intervalTiers[0]?.interval || 20; // default to idlest
  for (const tier of intervalTiers) {
    if (minsToDeparture <= tier.withinMin) {
      recommendedInterval = tier.interval;
      break;
    }
  }
}

return { json: {
  action: shouldUpdate ? 'update_state' : (sendUrgentAlert ? 'urgent_alert' : 'none'),
  event_id: event.event_id,
  user_id: userId,
  title: event.title,
  current_state: newState,
  previous_state: currentState,
  state_version: shouldUpdate ? stateVersion + 1 : stateVersion,
  expected_previous_version: stateVersion,  // for optimistic concurrency check before write
  stop_tracking: stopTracking,
  send_urgent_alert: sendUrgentAlert,
  ntfy_topic: event.ntfy_topic || allRows.find(r => r.user_id === userId)?.ntfy_topic,
  events_to_update: eventsToUpdate.length > 0 ? JSON.stringify(eventsToUpdate) : null,
  departed_at: event.departed_at || null,  // pass through for commute_history calc
  arrival_data: newState === 'arrived' ? JSON.stringify({
    planned_departure: event.departure_time,
    actual_departure: event.departed_at || null,
    planned_travel_min: parseInt(event.commute_minutes) || 0,
    actual_travel_min: event.departed_at
      ? Math.round((now.getTime() - new Date(event.departed_at).getTime()) / 60000)
      : null,
    commute_mode: event.commute_mode,
    destination_coords: event.location_coords,
    origin_coords: event.origin_coords
  }) : null,
  remaining_events: remainingAfterThis.length,
  user_is_at_home: userIsAtHome,
  at_home_source: atHomeSource,
  at_home_updates: eventsNeedingAtHomeUpdate.length > 0
    ? JSON.stringify(eventsNeedingAtHomeUpdate.map(r => r.event_id))
    : null,
  recommended_interval: recommendedInterval
}};

// Optimistic concurrency: verify state_version hasn't changed since our initial read
const rows = $input.all().map(i => i.json);
const stateData = $('Select Active Event + Run State Machine').item.json;

const currentRow = rows.find(r => r.event_id === stateData.event_id);

if (!currentRow) {
  // Row disappeared — log and skip
  return { json: { ...stateData, version_ok: false, reason: 'row_not_found' } };
}

const currentVersion = parseInt(currentRow.state_version) || 0;
const expectedVersion = stateData.expected_previous_version;

if (currentVersion !== expectedVersion) {
  // Another writer modified this row — abort to avoid overwriting their change
  return { json: { ...stateData, version_ok: false, reason: 'version_mismatch',
    expected: expectedVersion, actual: currentVersion } };
}

return { json: { ...stateData, version_ok: true } };

// Parse arrival_data JSON string from the state machine output
const data = JSON.parse($json.arrival_data);
const eventRow = $('Re-Read Event Row').first().json; // from Node 6a

const arrivedAt = $now.toISO();
const startTime = new Date(eventRow.start_time);
const arrivedTime = new Date();
const arrivedOnTime = arrivedTime <= new Date(startTime.getTime() + 5 * 60 * 1000); // 5-min grace
const delayMin = arrivedOnTime ? 0 : Math.max(0, Math.round((arrivedTime - startTime) / 60000));

return { json: {
  timestamp: arrivedAt,
  event_id: $json.event_id,
  user_id: $json.user_id,
  event_title: $json.title,
  plan_date: eventRow.plan_date,
  origin_coords: data.origin_coords || '',
  destination_coords: data.destination_coords || '',
  commute_mode: data.commute_mode || '',
  planned_departure: data.planned_departure || '',
  actual_departure: data.actual_departure || '',
  planned_travel_min: data.planned_travel_min || 0,
  actual_travel_min: data.actual_travel_min || 0,
  arrived_on_time: arrivedOnTime ? 'TRUE' : 'FALSE',
  arrival_delay_min: delayMin
}};

// Parse the list of events whose origin needs updating after arrival
const eventsToUpdate = JSON.parse($json.events_to_update);
const arrivalLocation = $json.arrival_data ? JSON.parse($json.arrival_data) : {};

return eventsToUpdate.map(evt => ({ json: {
  event_id: evt.event_id,
  new_origin_coords: evt.new_origin_coords,
  new_origin_type: evt.new_origin_type,
  user_id: $json.user_id,
  ntfy_topic: $json.ntfy_topic
}}));

// Recalculate reminder times with the new departure time
const departure = $('Recalculate Departure').item.json;
const weather = $json; // from Sub-WF B
const eventRow = $('Read Event Row').item.json;
const update = $('Loop Events To Update').item.json;

if (departure.error) {
  // Sub-WF A failed — keep existing departure, just update origin
  return { json: {
    event_id: update.event_id,
    origin_coords: update.new_origin_coords,
    origin_type: update.new_origin_type,
    state_version: (parseInt(eventRow.state_version) || 0) + 1,
    departure_changed: false
  }};
}

const depTime = new Date(departure.departure_time);
const fourAM = new Date(depTime);
fourAM.setHours(4, 0, 0, 0);

// Recalculate remind_dressed using DRESS_REMINDER_INTERVALS, filtered by dress_cap
const ALL_DRESS_INTERVALS = $vars.DRESS_REMINDER_INTERVALS.split(',').map(s => s.trim()).filter(Boolean).map(Number).filter(n => !isNaN(n));
const dressCap = parseInt(eventRow.dress_cap) || 0;
const DRESS_INTERVALS = dressCap > 0
  ? ALL_DRESS_INTERVALS.filter(n => n <= dressCap)
  : ALL_DRESS_INTERVALS;
const maxInterval = DRESS_INTERVALS.length > 0 ? Math.max(...DRESS_INTERVALS) : 0;
const dressedEarliest = maxInterval > 0
  ? new Date(depTime.getTime() - maxInterval * 60 * 1000)
  : depTime;
const remindDressed = dressedEarliest < fourAM ? fourAM : dressedEarliest;

// Note: at_home is NOT recalculated here. It's maintained by WF4's main flow
// (Nodes 12a-12c) based on real-time GPS position, not event locations.
// The at_home column is preserved by omitting it from this upsert.

// Determine which reminders have already been sent.
// When origin changes (e.g., arrived at event A, now heading to event B),
// the departure time shifts. We KEEP already-fired standard reminders (remind_60, remind_30, etc.)
// because they were correct at the time they fired. We CLEAR unfired dress reminders
// (remind_dressed_*) since the clothing advice may change with the new origin's weather.
const alreadySent = (eventRow.reminders_sent || '').split(',').map(s => s.trim()).filter(Boolean);

// Clear unfired dress reminders — they need to re-fire with updated clothing advice
const firedNonDress = alreadySent.filter(r => !r.startsWith('remind_dressed'));
const firedDress = alreadySent.filter(r => r.startsWith('remind_dressed'));
// Keep fired dress reminders (they already went to the user), only new dress times will re-fire
const keptReminders = [...firedNonDress, ...firedDress];

return { json: {
  event_id: update.event_id,
  origin_coords: update.new_origin_coords,
  origin_type: update.new_origin_type,
  departure_time: departure.departure_time,
  commute_minutes: departure.commute_minutes,
  commute_mode: departure.commute_mode,
  weather_worst: weather.weather_worst || eventRow.weather_worst || '',
  clothing_advice: weather.clothing_advice || eventRow.clothing_advice || '',
  remind_dressed: remindDressed.toISOString(),
  remind_60: new Date(depTime.getTime() - 60 * 60 * 1000).toISOString(),
  remind_30: new Date(depTime.getTime() - 30 * 60 * 1000).toISOString(),
  remind_15: new Date(depTime.getTime() - 15 * 60 * 1000).toISOString(),
  remind_now: departure.departure_time,
  reminders_sent: keptReminders.join(','),  // preserve already-sent, WF3 won't re-send those
  state_version: (parseInt(eventRow.state_version) || 0) + 1,
  departure_changed: true,
  old_departure: eventRow.departure_time,
  diff_minutes: Math.round(Math.abs(new Date(departure.departure_time) - new Date(eventRow.departure_time)) / 60000),
  ntfy_topic: update.ntfy_topic
}};

// Parse the list of event IDs that need at_home updated
const stateData = $('Select Active Event + Run State Machine').item.json;
const eventIds = JSON.parse(stateData.at_home_updates);
const newAtHome = stateData.user_is_at_home;

return eventIds.map(eventId => ({ json: {
  event_id: eventId,
  at_home: newAtHome
}}));
